package com.waddle2.feishuautopunch;
import android.Manifest; import android.content.*; import android.content.pm.PackageManager; import android.net.Uri; import android.os.Bundle; import android.provider.Settings; import android.widget.*; import androidx.appcompat.app.AppCompatActivity;
public class MainActivity extends AppCompatActivity {
 Switch enabled; TimePicker work, off; TextView status;
 @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);enabled=findViewById(R.id.switch_enabled);work=findViewById(R.id.time_work);off=findViewById(R.id.time_off);status=findViewById(R.id.txt_status);work.setHour(9);work.setMinute(0);off.setHour(18);off.setMinute(0);enabled.setChecked(AlarmReceiver.isEnabled(this));findViewById(R.id.btn_save).setOnClickListener(v->save());findViewById(R.id.btn_test).setOnClickListener(v->AlarmReceiver.launchFeishu(this,"手动测试"));findViewById(R.id.btn_exact_alarm).setOnClickListener(v->{if(android.os.Build.VERSION.SDK_INT>=31)startActivity(new Intent(Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM, Uri.parse("package:"+getPackageName())));});findViewById(R.id.btn_fullscreen).setOnClickListener(v->{if(android.os.Build.VERSION.SDK_INT>=34)startActivity(new Intent(Settings.ACTION_MANAGE_APP_USE_FULL_SCREEN_INTENT,Uri.parse("package:"+getPackageName())));});findViewById(R.id.btn_battery).setOnClickListener(v->{try{startActivity(new Intent(Settings.ACTION_REQUEST_IGNORE_BATTERY_OPTIMIZATIONS,Uri.parse("package:"+getPackageName())));}catch(Exception e){startActivity(new Intent(Settings.ACTION_IGNORE_BATTERY_OPTIMIZATION_SETTINGS));}});if(android.os.Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},10);update();}
 void save(){if(!enabled.isChecked()){AlarmReceiver.cancelAll(this);update();return;}AlarmReceiver.setEnabled(this,true);AlarmReceiver.scheduleDaily(this,0,work.getHour(),work.getMinute());AlarmReceiver.scheduleDaily(this,1,off.getHour(),off.getMinute());update();}
 void update(){status.setText(AlarmReceiver.diagnosticText(this));} @Override protected void onResume(){super.onResume();if(status!=null)update();}
}
